/** Regression coverage for LMDB initialization ordering, size reporting, and failed construction cleanup. */
public final class TripleStoreInitializationTest {

	private static final long INITIAL_MAP_SIZE = 8L * 1024 * 1024;
	private static final long AUTO_GROW_INITIAL_MAP_SIZE = INITIAL_MAP_SIZE / 256;
	private static final int PROBE_TIMEOUT_SECONDS = 30;
	private static final int PROBE_CLEANUP_TIMEOUT_SECONDS = 5;
	private static final String PROBE_PROPERTY = "rdf4j.lmdb.initializationProbe";
	private static final String FAILURE_MARKER = "OVERSIZED_INITIALIZATION_IOEXCEPTION";
	private static final String RECOVERY_MARKER = "OVERSIZED_INITIALIZATION_RECOVERY_OK";

	private record EnvironmentStats(int pageSize, long mapSize, long lastPageNumber) {
		long minimumMapSize() {
			return Math.multiplyExact(Math.addExact(lastPageNumber, 1), pageSize);
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void emptyInitializationReportsNativeMapSizeAndAlignment(boolean estimatorEnabled, @TempDir Path directory)
			throws Exception {
		long requestedSize = INITIAL_MAP_SIZE + 123;
		LmdbStoreConfig config = config(requestedSize, estimatorEnabled);
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			EnvironmentStats stats = environmentStats(store);
			assertTrue(stats.mapSize() > stats.minimumMapSize(), "The requested map must exceed native minimum usage");
			assertEquals(alignedSize(requestedSize, stats.pageSize()), stats.mapSize(),
					"An empty store should use the requested page-aligned map size");
			assertEquals(0, stats.mapSize() % stats.pageSize(),
					"LMDB map size must remain page aligned after initialization");
		}
	}

	@Test
	void populatedReopenRetainsDataAndDoesNotShrinkBelowConsumedMap(@TempDir Path directory) throws Exception {
		LmdbStoreConfig initialConfig = config(INITIAL_MAP_SIZE, true);
		long initialMapSize;
		int pageSize;
		try (TripleStore store = new TripleStore(directory.toFile(), initialConfig, null)) {
			store.startTransaction();
			store.storeTriple(1, 2, 3, 4, true);
			store.commit();
			EnvironmentStats initialStats = environmentStats(store);
			initialMapSize = initialStats.mapSize();
			pageSize = initialStats.pageSize();
		}
		new StoreProperties(directory.toFile()).setTripleIndexes("spoc,posc").save();

		long largerRequestedSize = initialMapSize * 2;
		long[] requestedSizes = { initialMapSize / 2, initialMapSize, largerRequestedSize };
		long[] expectedMapSizes = { initialMapSize, initialMapSize, alignedSize(largerRequestedSize, pageSize) };
		for (int index = 0; index < requestedSizes.length; index++) {
			long requestedSize = requestedSizes[index];
			StoreProperties properties = new StoreProperties(directory.toFile());
			assertTrue(properties.load(), "Reopen must load explicitly persisted store properties");
			try (TripleStore store = new TripleStore(directory.toFile(), properties, config(requestedSize, true),
					null)) {
				EnvironmentStats stats = environmentStats(store);
				assertEquals(expectedMapSizes[index], stats.mapSize(),
						"Populated reopen must preserve or use the requested aligned map size");
				assertEquals(pageSize, stats.pageSize());
				assertTrue(stats.mapSize() >= stats.minimumMapSize());
				assertEquals(1, countTriples(store));
				assertEquals(0, stats.mapSize() % stats.pageSize());
			}
		}
	}

	@Test
	void emptyInitializationClampsBelowConsumedPagesAndHandlesZeroOrSubpageSizes(@TempDir Path directory)
			throws Exception {
		EnvironmentStats initialStats;
		try (TripleStore store = new TripleStore(directory.toFile(), config(INITIAL_MAP_SIZE, false), null)) {
			initialStats = environmentStats(store);
		}
		new StoreProperties(directory.toFile()).setTripleIndexes("spoc,posc").save();

		long belowConsumedPages = Math.max(0, initialStats.minimumMapSize() - initialStats.pageSize());
		long[] requestedSizes = { belowConsumedPages, 0, initialStats.pageSize() - 1L };
		for (long requestedSize : requestedSizes) {
			StoreProperties properties = new StoreProperties(directory.toFile());
			assertTrue(properties.load(), "Reopen must load explicitly persisted store properties");
			try (TripleStore store = new TripleStore(directory.toFile(), properties, config(requestedSize, false),
					null)) {
				EnvironmentStats stats = environmentStats(store);
				assertEquals(initialStats.pageSize(), stats.pageSize());
				assertTrue(stats.mapSize() >= initialStats.minimumMapSize(),
						"Native initialization must clamp below the consumed page range");
				assertTrue(stats.mapSize() >= stats.minimumMapSize());
				assertEquals(0, stats.mapSize() % stats.pageSize());
			}
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void normalInitializationRetainsDataAfterAutomaticGrowth(boolean estimatorEnabled, @TempDir Path directory)
			throws Exception {
		LmdbStoreConfig config = config(AUTO_GROW_INITIAL_MAP_SIZE, estimatorEnabled);
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			long initialMapSize = environmentStats(store).mapSize();
			store.startTransaction();
			for (int index = 0; index < 4_000; index++) {
				store.storeTriple(index + 1L, 7, index + 10_000L, 3, true);
			}
			store.commit();
			assertTrue(environmentStats(store).mapSize() > initialMapSize,
					"A commit beyond the initial map must use the existing auto-growth path");
			assertEquals(4_000, countTriples(store));
		}
	}

	@ParameterizedTest(name = "oversized initialization recovery with estimator={0}, populated={1}")
	@CsvSource({ "false, false", "false, true", "true, false", "true, true" })
	void oversizedNonWriteMapInitializationFailsAndRecovers(boolean estimatorEnabled, boolean populated,
			@TempDir Path directory)
			throws Exception {
		Assumptions.assumeTrue(isSupportedOversizedProbePlatform(),
				"The oversized native map probe is limited to non-WRITEMAP 64-bit Linux/macOS");
		Path storeDirectory = directory.resolve("oversized-store");
		Files.createDirectories(storeDirectory);
		if (populated) {
			createPopulatedStore(storeDirectory, estimatorEnabled);
		}
		Path output = directory.resolve("oversized-initialization-" + estimatorEnabled + "-" + populated + ".log");

		Process process = startProbe(storeDirectory, estimatorEnabled, populated, output);
		try {
			boolean finished = process.waitFor(PROBE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			String probeOutput = Files.exists(output) ? Files.readString(output, StandardCharsets.UTF_8) : "";
			assertTrue(finished, "Oversized initialization probe timed out:\n" + probeOutput);
			assertEquals(0, process.exitValue(), probeOutput);
			assertTrue(probeOutput.contains(FAILURE_MARKER), probeOutput);
			assertTrue(probeOutput.contains(RECOVERY_MARKER), probeOutput);
		} finally {
			terminate(process);
		}
	}

	public static void main(String[] args) throws Exception {
		if (!Boolean.getBoolean(PROBE_PROPERTY) || args.length != 3) {
			throw new IllegalStateException("This class is an initialization child-JVM probe");
		}
		Path directory = Path.of(args[0]);
		boolean estimatorEnabled = Boolean.parseBoolean(args[1]);
		boolean populated = Boolean.parseBoolean(args[2]);
		try {
			try (TripleStore ignored = openProbeStore(directory, estimatorEnabled, populated, Long.MAX_VALUE)) {
				throw new AssertionError("Long.MAX_VALUE map initialization unexpectedly succeeded");
			}
		} catch (IOException expected) {
			System.out.println(FAILURE_MARKER + " " + expected.getMessage());
		}

		try (TripleStore recovered = openProbeStore(directory, estimatorEnabled, populated, INITIAL_MAP_SIZE)) {
			int existingTriples = countTriples(recovered);
			assertEquals(populated ? 1 : 0, existingTriples);
			if (populated) {
				assertTrue(containsTriple(recovered, 1, 2, 3, 4, true),
						"Original populated data must survive recovery");
			}
			recovered.startTransaction();
			long newSubject = populated ? 201 : 101;
			recovered.storeTriple(newSubject, 202, 203, 204, true);
			recovered.commit();
			assertTrue(containsTriple(recovered, newSubject, 202, 203, 204, true),
					"Recovered store must accept a new write");
			assertEquals(existingTriples + 1, countTriples(recovered));
		}
		System.out.println(RECOVERY_MARKER);
	}

	private static Process startProbe(Path directory, boolean estimatorEnabled, boolean populated, Path output)
			throws IOException {
		String javaBinary = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		List<String> command = new ArrayList<>();
		command.add(javaBinary);
		command.add("-ea");
		command.add("-XX:-CreateCoredumpOnCrash");
		command.add("-XX:ErrorFile=" + output.getParent().resolve("hs_err_pid%p.log"));
		command.add("--enable-native-access=ALL-UNNAMED");
		command.add("-D" + PROBE_PROPERTY + "=true");
		command.add("-cp");
		command.add(System.getProperty("java.class.path"));
		command.add(TripleStoreInitializationTest.class.getName());
		command.add(directory.toAbsolutePath().toString());
		command.add(Boolean.toString(estimatorEnabled));
		command.add(Boolean.toString(populated));
		return new ProcessBuilder(command)
				.redirectErrorStream(true)
				.redirectOutput(output.toFile())
				.start();
	}

	private static LmdbStoreConfig config(long tripleDatabaseSize, boolean estimatorEnabled) {
		return new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(tripleDatabaseSize)
				.setPageCardinalityEstimator(estimatorEnabled);
	}

	private static long alignedSize(long value, int pageSize) {
		return (value / pageSize) * pageSize;
	}

	private static EnvironmentStats environmentStats(TripleStore store) {
		try (MemoryStack stack = stackPush()) {
			MDBStat stat = MDBStat.malloc(stack);
			assertEquals(MDB_SUCCESS, mdb_env_stat(store.env, stat));
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			assertEquals(MDB_SUCCESS, mdb_env_info(store.env, info));
			return new EnvironmentStats(stat.ms_psize(), info.me_mapsize(), info.me_last_pgno());
		}
	}

	private static void createPopulatedStore(Path directory, boolean estimatorEnabled) throws Exception {
		try (TripleStore store = new TripleStore(directory.toFile(), config(INITIAL_MAP_SIZE, estimatorEnabled),
				null)) {
			store.startTransaction();
			store.storeTriple(1, 2, 3, 4, true);
			store.commit();
		}
		new StoreProperties(directory.toFile()).setTripleIndexes("spoc,posc").save();
	}

	private static TripleStore openProbeStore(Path directory, boolean estimatorEnabled, boolean populated,
			long mapSize) throws Exception {
		if (populated) {
			StoreProperties properties = new StoreProperties(directory.toFile());
			if (!properties.load()) {
				throw new IOException("Populated probe store properties were not persisted");
			}
			return new TripleStore(directory.toFile(), properties, config(mapSize, estimatorEnabled), null);
		}
		return new TripleStore(directory.toFile(), config(mapSize, estimatorEnabled), null);
	}

	private static int countTriples(TripleStore store) throws IOException {
		try (Txn txn = store.getTxnManager().createReadTxn();
				RecordIterator iterator = store.getTriples(txn, -1, -1, -1,
						-1, true)) {
			int count = 0;
			while (iterator.next() != null) {
				count++;
			}
			return count;
		}
	}

	private static boolean containsTriple(TripleStore store, long subject, long predicate, long object, long context,
			boolean explicit) throws IOException {
		try (Txn txn = store.getTxnManager().createReadTxn();
				RecordIterator iterator = store.getTriples(txn, subject, predicate, object, context, explicit)) {
			return iterator.next() != null;
		}
	}

	private static boolean isSupportedOversizedProbePlatform() {
		String os = System.getProperty("os.name", "").toLowerCase(Locale.ROOT);
		return (os.contains("linux") || os.contains("mac")) && Pointer.POINTER_SIZE == 8;
	}

	private static void terminate(Process process) throws InterruptedException {
		if (!process.isAlive()) {
			return;
		}
		process.destroyForcibly();
		if (!process.waitFor(PROBE_CLEANUP_TIMEOUT_SECONDS, TimeUnit.SECONDS)) {
			throw new AssertionError("Child probe did not exit after forced cleanup");
		}
	}
}
